package com.dealhunter.app;
import android.app.*;import android.os.*;import android.content.*;import android.net.Uri;import android.graphics.Color;import android.widget.*;import android.view.*;import androidx.work.*;import java.util.concurrent.TimeUnit;import org.json.*;
public class MainActivity extends Activity {
 LinearLayout root, feed; TextView status; int minimum=50; boolean saved=false;
 android.content.SharedPreferences prefs;
 TextView text(String s,int size){TextView t=new TextView(this);t.setText(s);t.setTextSize(size);t.setTextColor(Color.WHITE);t.setPadding(16,12,16,12);return t;}
 Button button(String s,Runnable r){Button b=new Button(this);b.setText(s);b.setOnClickListener(v->r.run());return b;}
 public void onCreate(Bundle b){super.onCreate(b);prefs=getSharedPreferences("deals",0);root=new LinearLayout(this);root.setOrientation(1);root.setPadding(20,48,20,24);root.setBackgroundColor(0xff111827);setContentView(root);root.addView(text("DEALHUNTER",30));root.addView(text("Men’s style. Better prices.",16));LinearLayout nav=new LinearLayout(this);nav.addView(button("Discover",()->{saved=false;render();}));nav.addView(button("Saved",()->{saved=true;render();}));nav.addView(button("Alerts",()->settings()));root.addView(nav);Spinner filter=new Spinner(this);filter.setAdapter(new ArrayAdapter<String>(this,android.R.layout.simple_spinner_dropdown_item,new String[]{"50%+ off","60%+ off","70%+ off","80%+ off","90%+ off"}));filter.setOnItemSelectedListener(new android.widget.AdapterView.OnItemSelectedListener(){public void onNothingSelected(AdapterView<?> p){}public void onItemSelected(AdapterView<?> p,View v,int pos,long id){minimum=50+pos*10;render();}});root.addView(filter);root.addView(button("Refresh deals",()->refresh()));status=text("",14);root.addView(status);ScrollView scroll=new ScrollView(this);feed=new LinearLayout(this);feed.setOrientation(1);scroll.addView(feed);root.addView(scroll,new LinearLayout.LayoutParams(-1,0,1));if(Build.VERSION.SDK_INT>=33)requestPermissions(new String[]{"android.permission.POST_NOTIFICATIONS"},1);WorkManager.getInstance(this).enqueueUniquePeriodicWork("deal-scan",ExistingPeriodicWorkPolicy.KEEP,new PeriodicWorkRequest.Builder(DealWorker.class,30,TimeUnit.MINUTES).setConstraints(new Constraints.Builder().setRequiredNetworkType(NetworkType.CONNECTED).build()).build());render();refresh();}
 void settings(){String[] choices={"Off","60%+","70%+","80%+","90%+"};int[] values={101,60,70,80,90};new AlertDialog.Builder(this).setTitle("Notify me about").setItems(choices,(d,i)->{prefs.edit().putInt("alert",values[i]).apply();}).show();}
 void refresh(){status.setText("Checking sources…");new Thread(()->{DealWorker.scan(this);runOnUiThread(()->render());}).start();}
 void render(){if(feed==null)return;feed.removeAllViews();status.setText(prefs.getString("status","No scan yet"));try{JSONArray a=new JSONArray(prefs.getString(saved?"saved":"results","[]"));int count=0;for(int i=0;i<a.length();i++){JSONObject d=a.getJSONObject(i);if(!saved&&d.getInt("discount")<minimum)continue;count++;LinearLayout card=new LinearLayout(this);card.setOrientation(1);card.setBackgroundColor(0xff253246);TextView heading=text(d.getInt("discount")+"% OFF",24);heading.setTextColor(0xff6ee7b7);card.addView(heading);card.addView(text(d.getString("title"),18));card.addView(text(d.getString("source")+" · Advertised, not verified",12));card.addView(button("View deal",()->startActivity(new Intent(Intent.ACTION_VIEW,Uri.parse(d.optString("url"))))));card.addView(button(saved?"Remove":"Save",()->{try{JSONArray old=new JSONArray(prefs.getString("saved","[]")), next=new JSONArray();for(int k=0;k<old.length();k++)if(!old.getJSONObject(k).optString("url").equals(d.optString("url")))next.put(old.getJSONObject(k));if(!saved)next.put(d);prefs.edit().putString("saved",next.toString()).apply();render();}catch(Exception e){}}));LinearLayout.LayoutParams lp=new LinearLayout.LayoutParams(-1,-2);lp.bottomMargin=16;feed.addView(card,lp);}if(count==0)feed.addView(text(saved?"No saved deals":"No matching deals available.",18));}catch(Exception e){status.setText("Unable to read saved results");}}
}
